'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=NavEngine,F=DonghaengFinal;
const read=k=>{try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{toast('브라우저 저장 공간에 접근할 수 없어요.');return false}};
let graph,map,origin=F.STATION.slice(),originName='월곡역 · 시연 기준점',destination=null,profile,analyzed='',routes=[],selected=0,watchId=null,currentStep=-1,detailGroups=[],toastTimer,pickMode=null,gpsMarker,accuracyCircle;
let journeyStages=[],activeStage=0,facilityController,facilityFeatures=[],localDestinations=[];
const stageMarkers=L.layerGroup(),stageFocus=L.layerGroup();
const pins={},routeLayer=L.layerGroup(),snapLayer=L.layerGroup();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function textEl(tag,text,className){const e=document.createElement(tag);e.textContent=text;if(className)e.className=className;return e}
function icon(type,text){return L.divIcon({className:'map-pin '+type,html:`<span>${text}</span>`,iconSize:[30,30],iconAnchor:[15,15]})}
function placePin(type,ll,title){if(pins[type])pins[type].remove();pins[type]=L.marker(ll,{icon:icon(type,type==='origin'?'출':'도'),draggable:true,autoPan:true,title}).addTo(map).bindTooltip(title,{direction:'top'});pins[type].on('dragend',()=>{const p=pins[type].getLatLng(),ll=[p.lat,p.lng];if(type==='origin')setOrigin(ll,'지도에서 지정한 출발지');else setDestination({ll,name:'지도에서 지정한 목적지'},{pan:false})})}
function invalidate(message='조건이 바뀌었어요. 길 찾기를 눌러 다시 계산해 주세요.'){if(routes.length){routes=[];routeLayer.clearLayers();snapLayer.clearLayers();$('#routes').replaceChildren(textEl('p',message,'empty-note'));$('#result-title').textContent='다시 길 찾기'}clearOrder();if(isMobileUI()&&mobileMode!=='input')setMobileMode('input');$('#route-callout').hidden=true;$('#plan-reason').hidden=true;stopTracking(false)}
function setOrigin(ll,name){origin=ll;originName=name;$('#origin-name').textContent=name;placePin('origin',ll,name);invalidate();$('#location-status').textContent='실제 출입구와 보행로를 확인해 출발 핀을 조정할 수 있어요.'}
function setDestination(place,{pan=true}={}){destination=place;$('#destination-query').value=place.name;$('#destination-status').textContent='선택됨 · '+place.name;$('#destination-status').dataset.selected='true';$('#places').replaceChildren();placePin('destination',place.ll,place.name);invalidate();if(pan){if(isMobileUI())frameVisibleLocation(place.ll,map.getZoom());else map.panTo(place.ll)}}
let analysisRequest=null,analysisVersion=0,autoAnalyzedText='';
function searchLabel(label='내 상태에 맞는 길 찾기'){$('#find-route').replaceChildren(document.createTextNode(label+' '),textEl('span','→'))}
function cancelAnalysis(){analysisVersion++;if(analysisRequest){analysisRequest.abort();analysisRequest=null}searchLabel();$('#search').removeAttribute('aria-busy');if(graph)$('#find-route').disabled=false}
function conditionChanged(){cancelAnalysis();autoAnalyzedText='';profile=null;analyzed='';invalidate();$('#parser-note').textContent='길 찾기를 누르면 AI가 문장을 해석해 이동 조건을 자동으로 반영해요.';$('#search-status').textContent='상태를 바꿨어요. 길 찾기를 눌러 주세요.'}
function setCondition(text){$('#condition').value=text;conditionChanged()}
function applyProfile(next,source){profile=E.wheelchairProfile({...next,avoidSteps:next.avoidSteps||next.wheelchair,avoidSlope:next.avoidSlope||next.wheelchair});analyzed=$('#condition').value;$('#parser-note').textContent=source+' · '+(profile.recognized?'이동 조건을 경로에 반영했어요.':'추가 이동 제약을 찾지 못해 기본 보행 경로를 추천해요. 상태를 구체적으로 적으면 다시 반영해요.')+(profile.restMinutes?` · ${profile.restMinutes}분 휴식 간격 요청`:'');return profile}
async function analyzeWithGemini(){const raw=$('#condition').value;if(!raw.trim()){toast('먼저 현재 상태를 적어 주세요.');return false}cancelAnalysis();invalidate();if(location.protocol==='file:'){applyProfile(E.parseState(raw),'파일 실행 · AI 서버 미연결, 기기 내 문장 규칙으로 해석');return true}const version=analysisVersion,controller=new AbortController();analysisRequest=controller;$('#find-route').disabled=true;$('#search').setAttribute('aria-busy','true');searchLabel('AI가 상태를 해석하고 있어요…');$('#parser-note').textContent='입력한 상태 문장으로 이동 조건을 확인하고 있어요.';const deadline=setTimeout(()=>controller.abort(),18000);try{const response=await fetch('/api/analyze-condition',{method:'POST',headers:{'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({condition:raw})});const data=await response.json();if(version!==analysisVersion||raw!==$('#condition').value)return false;if(!response.ok)throw Error(data.error||'AI 연결에 실패했어요.');applyProfile(ConditionAI.merge(E.parseState(raw),data.profile),'Gemini 해석 · 입력 상태 문장만 전송');autoAnalyzedText=raw;return true}catch(error){if(version!==analysisVersion||raw!==$('#condition').value)return false;applyProfile(E.parseState(raw),'AI 연결 실패 · 기기 내 해석');autoAnalyzedText='';$('#parser-note').textContent=(error.name==='AbortError'?'AI 응답 시간이 초과됐어요.':error.message)+' 기기 내 문장 규칙으로 경로를 추천해요. 길 찾기를 다시 누르면 AI 연결을 재시도해요.';return true}finally{clearTimeout(deadline);if(version===analysisVersion){analysisRequest=null;searchLabel();$('#search').removeAttribute('aria-busy');$('#find-route').disabled=!graph}}}
function effectiveProfile(){if(!profile||analyzed!==$('#condition').value)throw Error('상태를 다시 입력하고 길 찾기를 눌러 주세요.');return {...profile}}
$$('[data-example]').forEach(b=>b.onclick=()=>setCondition(b.dataset.example));$('#condition').oninput=conditionChanged;
function searchPlaces(){if(!graph)return;const q=$('#destination-query').value.trim().toLowerCase().replace(/\s/g,''),items=localDestinations.filter(p=>!q||p.name.toLowerCase().replace(/\s/g,'').includes(q)).slice(0,10);$('#places').replaceChildren();items.forEach(p=>{const button=textEl('button',p.name);button.type='button';button.append(textEl('small',`${Math.round(E.distance(origin,p.ll))}m 직선거리 · ${p.type==='seating'?'의자 있는 장소':p.type==='bench'?'벤치':p.type==='bus_stop'?'정류장':'주변 장소'}`));button.onclick=()=>setDestination(p);$('#places').append(button)});if(!items.length)$('#places').append(textEl('p','해당 장소가 없어요. 지도에서 목적지를 지정해 주세요.','empty-note'))}
$('#destination-query').oninput=()=>{delete $('#destination-status').dataset.selected;destination=null;invalidate();$('#destination-status').textContent='검색 결과에서 목적지를 선택해 주세요.';searchPlaces()};$('#destination-query').onfocus=searchPlaces;
function chooseOnMap(mode){pickMode=mode;if(isMobileUI())setSheetSize('collapsed');$('#map-instruction').hidden=false;$('#map-instruction').textContent=(mode==='origin'?'출발':'도착')+'할 보행로를 지도에서 눌러 주세요. 같은 버튼을 다시 누르면 취소돼요.';$('#live-map').scrollIntoView({behavior:'smooth',block:'center'});map.invalidateSize()}
$('#pick-origin').onclick=()=>{if(pickMode==='origin'){pickMode=null;$('#map-instruction').hidden=true}else chooseOnMap('origin')};$('#pick-destination').onclick=()=>{if(pickMode==='destination'){pickMode=null;$('#map-instruction').hidden=true}else chooseOnMap('destination')};
function getPosition(){if(!navigator.geolocation){toast('이 브라우저는 위치 기능을 지원하지 않아요. 지도에서 출발지를 선택해 주세요.');return}$('#locate').disabled=true;$('#location-status').textContent='위치 권한을 허용해 주세요. 현재 위치를 확인하고 있어요…';navigator.geolocation.getCurrentPosition(pos=>{$('#locate').disabled=false;const ll=[pos.coords.latitude,pos.coords.longitude];setOrigin(ll,'현재 위치 · GPS');$('#location-status').textContent=`GPS 정확도 약 ${Math.round(pos.coords.accuracy)}m${pos.coords.accuracy>80?' · 오차가 커요. 출발 핀을 보정해 주세요.':''}`;if(accuracyCircle)accuracyCircle.remove();accuracyCircle=L.circle(ll,{radius:pos.coords.accuracy,color:'#4b8aba',weight:1,fillOpacity:.08}).addTo(map);if(isMobileUI())frameVisibleLocation(ll,17);else map.setView(ll,17);if(!F.inCoverage(ll))toast('현재 위치는 경로 데이터 범위 밖이에요. 월곡역으로 버튼을 누르거나 지도에서 출발지를 지정해 주세요.')},err=>{$('#locate').disabled=false;$('#location-status').textContent=err.code===1?'위치 권한이 거부됐어요. 브라우저 설정에서 허용하거나 지도에서 출발지를 지정해 주세요.':'위치를 확인하지 못했어요. 실외에서 다시 시도하거나 지도에서 출발지를 지정해 주세요.'},{enableHighAccuracy:true,timeout:15000,maximumAge:10000})}
$('#locate').onclick=getPosition;
function resetTrip(){if(!graph)return;setOrigin(F.STATION.slice(),'월곡역 · 시연 기준점');$('#location-status').textContent='GPS 위치가 아닌 월곡역 시연 기준점이에요. 실제 출입구에 맞춰 핀을 보정할 수 있어요.';const library=localDestinations.find(p=>p.name==='월곡꿈그림도서관');if(library)setDestination(library,{pan:false});map.setView(F.STATION,17,{animate:false});if(isMobileUI())frameVisibleLocation(origin,17)}
$('#school-reset').onclick=()=>{resetTrip();toast('월곡역 시연 위치로 돌아왔어요.')};
$('#search').onsubmit=async ev=>{ev.preventDefault();if(!graph)return;if(analysisRequest){toast('이동 조건을 확인하고 있어요. 잠시 기다려 주세요.');return}if(!destination){toast('검색 결과에서 목적지를 선택하거나 지도를 눌러 주세요.');return}if(!F.inCoverage(origin)||!F.inCoverage(destination.ll)){$('#search-status').textContent='경로 탐색은 월곡역·학교 주변 내장 도로망에서 지원해요. 월곡역으로 돌아오거나 가까운 목적지를 선택해 주세요.';return}if(isMobileUI()){document.activeElement?.blur();setSheetSize('default')}const requestText=$('#condition').value,tripKey=JSON.stringify([origin,destination.ll]);if(autoAnalyzedText!==requestText||!profile){$('#search-status').textContent='AI가 상태를 해석한 뒤 경사·벤치·쉼터를 반영해 경로를 추천합니다…';const applied=await analyzeWithGemini();if(!applied||requestText!==$('#condition').value||tripKey!==JSON.stringify([origin,destination?.ll]))return}const p=effectiveProfile(),routeVersion=analysisVersion;$('#find-route').disabled=true;searchLabel('맞춤 경로를 찾고 있어요…');$('#search-status').textContent='실제 도로 그래프에서 이동 조건에 맞는 경로를 계산하고 있어요…';await new Promise(requestAnimationFrame);if(routeVersion!==analysisVersion||requestText!==$('#condition').value||tripKey!==JSON.stringify([origin,destination?.ll])){searchLabel();$('#find-route').disabled=false;return}try{const fitted=E.route(graph,origin,destination.ll,p);routes=[{...fitted,label:fitted.assistancePreview?'이동 지원 필요 · 경사 위험 대안':p.wheelchair?'경사 회피 우회 후보 · 통행 미확인':p.rest?(fitted.restStop?.kind==='shelter'?'쉼터를 경유하는 맞춤 경로':'쉬어 가는 맞춤 경로'):'내 상태를 반영한 경로',p}];const basic=E.route(graph,origin,destination.ll,{speed:p.speed,short:true});if(!p.wheelchair&&basic.ids.join(',')!==fitted.ids.join(','))routes.push({...basic,label:'일반 최단 경로 · 비교용',p:{...p,avoidSteps:false,avoidSlope:false,maxSlope:null,rest:false,short:true},comparison:true});selected=0;if(isMobileUI())setMobileMode('results');renderRoutes();drawRoutes(true);$('#search-status').textContent=fitted.assistancePreview?'급경사 회피 조건을 만족하는 경로가 없어요. 위험 구간이 표시된 검토용 대안이며, 휠체어 독립 이동 추천이 아닙니다.':p.rest?(fitted.restStop?'의자·휴식 장소를 경유해요. 진입과 현재 상태는 현장에서 확인해 주세요.':'휴식 조건을 만족하는 경유지를 찾지 못했어요. 결과의 제한 사항을 확인해 주세요.'):(p.wheelchair?'휠체어 경사 회피 규칙으로 우회 후보를 찾았어요. 경사 미확인·진입 구간의 통행 여부는 확인이 필요해요.':routes.length===1?'현재 데이터에서는 맞춤 경로와 일반 최단 경로가 같아요.':'이동 조건을 적용해 일반 최단 경로와 비교했어요.');$('#result-title').textContent=fitted.assistancePreview?'경사 위험 대안 · 이동 지원 필요':'내 상태에 맞춘 경로';renderPlanReason(fitted,p);updateRouteCallout();if(isMobileUI())$('.sheet-scroll').scrollTop=0;else $('#routes').scrollIntoView({behavior:'smooth',block:'start'})}catch(e){routes=[];routeLayer.clearLayers();snapLayer.clearLayers();$('#routes').replaceChildren();clearOrder();$('#search-status').textContent=e.message;if(isMobileUI())setMobileMode('input')}finally{searchLabel();$('#find-route').disabled=false}};
function renderRoutes(){const c=$('#routes');c.replaceChildren();$('#mobile-route-action').replaceChildren();routes.forEach((r,i)=>{const card=textEl('article','','route-card'+(selected===i?' selected':'')+(r.assistancePreview?' risk-preview':''));const choose=textEl('button','');choose.type='button';choose.style.cssText='border:0;background:transparent;padding:0;width:100%;text-align:left';choose.setAttribute('aria-pressed',selected===i);choose.setAttribute('aria-label',r.label);const top=textEl('div','','route-header');top.append(textEl('span',r.label,'route-tag'+(r.comparison?' tag-gray':'')),textEl('span','','select-circle'));const time=textEl('div',Math.max(1,Math.ceil((r.totalLength||r.length)/r.p.speed))+'분','route-time');time.append(textEl('em',Math.round(r.totalLength||r.length)+'m · 연결 구간 포함 추정'));const stairs=r.edges.filter(e=>e.steps).reduce((a,e)=>a+e.d,0),features=textEl('div','','route-features');features.append(textEl('span','등록 계단 '+(stairs?Math.round(stairs)+'m':'0구간')),textEl('span',r.screeningMeters?'자료 차이·구조물 '+Math.round(r.screeningMeters.range+r.screeningMeters.structure)+'m':'경사 미확인 '+Math.round(r.unknown)+'m'));choose.append(top,time,features);if(r.maxEstimatedSlope!=null)choose.append(textEl('p',`Tilezen 도로 창 평균 추정 최대 약 ${r.maxEstimatedSlope.toFixed(1)}% · 보도 실측 아님`,'slope-summary'));if(r.restStop)choose.append(textEl('p',`☕ ${r.restStop.name} · 약 ${Math.ceil(r.restStop.firstDistance/r.p.speed)}분 뒤 휴식`,'route-description'));choose.onclick=()=>{selected=i;renderRoutes();drawRoutes(true)};card.append(choose);if(r.comparison)card.append(textEl('p','입력한 이동 제약을 적용하지 않은 비교 경로입니다.','route-status'));const warns=textEl('div',r.messages.join(' '),'route-warnings'),limits=textEl('details','','route-limits');limits.open=!isMobileUI();limits.append(textEl('summary','제한·연결 구간 확인'),warns);card.append(limits);limits.append(textEl('p',`출발점→도로 약 ${Math.round(r.gaps[0])}m / 도로→목적지 약 ${Math.round(r.gaps[1])}m는 미검증 연결입니다. 연결 구간은 실제 진입 동선과 다를 수 있어요.`,'gap-note'));if(selected===i){card.append(textEl('p',r.assistancePreview?'이동 지원 필요 · 독립 이동 추천 아님':r.comparison?'상태 제약 미적용 · 비교용':'현장 통행 미확인','mobile-card-notice mobile-only'));const go=textEl('button',isMobileUI()?'이동 순서 보기 →':'구간 자세히 보기 →','route-go');go.onclick=()=>{if(isMobileUI()){setMobileMode('order');selectStage(0,true)}else showDetails()};if(isMobileUI())$('#mobile-route-action').append(go);else card.append(go)}c.append(card)})}
function drawRoutes(fit){routeLayer.clearLayers();snapLayer.clearLayers();routes.forEach((r,i)=>{if(i===selected)return;L.polyline(r.coords,{color:'#8d9895',weight:5,opacity:.8,dashArray:'7 8'}).addTo(routeLayer)});const r=routes[selected];if(!r)return;L.polyline(r.coords,{color:'white',weight:12,opacity:.95}).addTo(routeLayer);L.polyline(r.coords,{color:r.assistancePreview?'#b63c32':'#176d52',weight:7,opacity:.95}).addTo(routeLayer);r.edges.forEach((e,i)=>{const info=e.slopeScreening,grade=E.screeningGrade(e),color=grade>(r.p.maxSlope??5)?'#c5352f':info?.kind==='source_range'?'#d9871d':info?.kind==='structure_unresolved'||info?.kind==='no_dem'?'#8653a3':null;if(color)L.polyline([r.coords[i],r.coords[i+1]],{color,weight:8,opacity:.95}).bindTooltip(slopeDescription(e)).addTo(routeLayer)});[[origin,r.from],[r.to,destination.ll]].forEach(coords=>L.polyline(coords,{color:'#cc9344',weight:3,dashArray:'4 6'}).bindTooltip('도로까지 미검증 연결 · 현장에서 확인').addTo(snapLayer));if(r.restStop)L.polyline([r.restStop.snap,r.restStop.ll],{color:'#cc9344',weight:3,dashArray:'4 6'}).addTo(snapLayer);if(fit)fitMobileAware(L.latLngBounds([...r.coords,origin,destination.ll]));buildOrder(r);renderPlanReason(r,r.p);updateRouteCallout()}
$('#fit-route').onclick=()=>{if(routes.length)drawRoutes(true);else map.setView(F.STATION,17);if(innerWidth<=700)$('#live-map').scrollIntoView({behavior:'smooth',block:'center'})};

function clearOrder(){journeyStages=[];stageMarkers.clearLayers();stageFocus.clearLayers();$('#route-order').hidden=true;$('#order-list').replaceChildren()}
function bearing(a,b){return Math.atan2((b[1]-a[1])*Math.cos(a[0]*Math.PI/180),b[0]-a[0])*180/Math.PI}
function turnLabel(previous,coords){if(!previous||previous.length<2||coords.length<2)return '→';const delta=(bearing(coords[0],coords[1])-bearing(previous.at(-2),previous.at(-1))+540)%360-180;return Math.abs(delta)>150?'↶':delta>35?'↱':delta< -35?'↰':'↑'}
function buildOrder(r){clearOrder();const groups=[];let previous=null;for(let i=0;i<r.edges.length;i++){const e=r.edges[i],last=groups.at(-1);if(last&&!last.bench&&last.name===e.name&&last.steps===e.steps){last.length+=e.d;last.coords.push(r.coords[i+1])}else{const coords=[r.coords[i],r.coords[i+1]],arrow=turnLabel(previous,coords);groups.push({name:e.name,length:e.d,coords,steps:e.steps,arrow})}previous=[r.coords[i],r.coords[i+1]];if(r.restStop&&E.distance(r.coords[i+1],r.restStop.snap)<1&&!groups.some(g=>g.bench))groups.push({name:r.restStop.name+'에서 쉬어가기',bench:true,coords:[r.restStop.snap,r.restStop.ll],length:0,gap:r.restStop.gap})}
journeyStages=[{title:'출발 · '+originName,sub:`보행로까지 약 ${Math.round(r.gaps[0])}m · 연결은 현장에서 확인`,coords:[origin,r.from],kind:'start',arrow:'출'},...groups.map(g=>({...g,title:g.bench?g.name:`${g.name} 따라 ${Math.round(g.length)}m 이동`,sub:g.bench?`보행로에서 약 ${Math.round(g.gap)}m · 휴식 장소 상태 미확인`:g.steps?'계단 구간 · 주의해서 확인하세요.':`${g.arrow==='↱'?'오른쪽으로 방향 전환':g.arrow==='↰'?'왼쪽으로 방향 전환':g.arrow==='↶'?'반대 방향으로 전환':'길을 따라 이어서 이동'} · 지도 기준 안내`,kind:g.bench?'rest':'walk',arrow:g.bench?'☕':g.arrow})),{title:'도착 · '+destination.name,sub:`도로에서 목적지까지 약 ${Math.round(r.gaps[1])}m · 출입구는 현장 확인`,coords:[r.to,destination.ll],kind:'finish',arrow:'도'}];activeStage=0;$('#route-order').hidden=false;renderOrder();journeyStages.forEach((stage,i)=>{if(stage.kind==='start'||stage.kind==='finish')return;const ll=stage.kind==='rest'?stage.coords.at(-1):stage.coords[Math.floor(stage.coords.length/2)],marker=L.marker(ll,{icon:L.divIcon({className:'order-map-marker'+(stage.kind==='rest'?' rest-marker':''),html:`<span>${i+1}</span>`,iconSize:[25,25],iconAnchor:[12,12]}),title:`${i+1}. ${stage.title}`,keyboard:true}).addTo(stageMarkers);marker.bindTooltip(`${i+1}. ${stage.title}`);marker.on('click',()=>selectStage(i,true))})}
function renderOrder(){const c=$('#order-list');c.replaceChildren();journeyStages.forEach((stage,i)=>{const li=document.createElement('li'),button=textEl('button','','order-step'+(i===activeStage?' is-current':'')+(stage.kind==='rest'?' is-rest':''));button.type='button';if(i===activeStage)button.setAttribute('aria-current','step');button.setAttribute('aria-label',`${i+1}단계. ${stage.title}. ${stage.sub}`);const number=textEl('span',String(i+1),'order-number'),body=textEl('span','','order-step-body');body.append(textEl('b',stage.title),textEl('small',stage.sub));button.append(number,body,textEl('span',stage.arrow,'order-arrow'));button.onclick=()=>selectStage(i,true);li.append(button);c.append(li)});renderMobileStage();$('#order-progress').textContent=`${activeStage+1} / ${journeyStages.length} 단계`;$('#order-prev').disabled=activeStage===0;$('#order-next').disabled=activeStage===journeyStages.length-1;$('#order-next').textContent=activeStage===journeyStages.length-2?'도착 지점 보기 →':'다음 구간 →';const row=c.children[activeStage];if(row){const rb=row.getBoundingClientRect(),cb=c.getBoundingClientRect();if(rb.top<cb.top)c.scrollTop-=cb.top-rb.top;else if(rb.bottom>cb.bottom)c.scrollTop+=rb.bottom-cb.bottom}}
function selectStage(index,fit){if(index<0||index>=journeyStages.length)return;activeStage=index;renderOrder();stageFocus.clearLayers();const stage=journeyStages[index];L.polyline(stage.coords,{color:'#fff',weight:17,opacity:1}).addTo(stageFocus);L.polyline(stage.coords,{color:'#e09a36',weight:9,opacity:1}).addTo(stageFocus);L.circleMarker(stage.coords.at(-1),{color:'white',weight:3,radius:9,fillColor:'#d18a27',fillOpacity:1}).addTo(stageFocus);if(fit)fitMobileAware(L.latLngBounds(stage.coords));if(innerWidth<=700)$('#live-map').scrollIntoView({behavior:'smooth',block:'center'})}
$('#order-prev').onclick=()=>selectStage(activeStage-1,true);$('#order-next').onclick=()=>selectStage(activeStage+1,true);

function groupSteps(r){const groups=[];for(const e of r.edges){const last=groups.at(-1);if(last&&last.id===e.id){last.length+=e.d;last.slopeEvidenceEdges.push(e);const grade=E.screeningGrade(e);if(grade>(last.screeningMax??-1)||['source_range','structure_unresolved','no_dem'].includes(e.slopeScreening?.kind)){last.slopeScreeningText=slopeDescription(e);last.screeningMax=grade??last.screeningMax}if(e.terrainSlope!=null)last.terrainSlope=Math.max(last.terrainSlope||0,e.terrainSlope)}else groups.push({id:e.id,name:e.name,length:e.d,steps:e.steps,incline:e.incline,terrainSlope:e.terrainSlope??null,slopeScreeningText:slopeDescription(e),slopeEvidenceEdges:[e]});if(r.restStop&&E.distance(graph.nodes.get(e.to).ll,r.restStop.snap)<1&&!groups.some(x=>x.bench))groups.push({id:'bench',name:r.restStop.name+'에서 쉬어가기',length:0,bench:true,gap:r.restStop.gap})}return groups}
function showDetails(){const r=routes[selected];if(!r)return;currentStep=-1;detailGroups=groupSteps(r);$('#detail-title').textContent=r.label;$('#detail-summary').textContent=`${originName} → ${destination.name} · 약 ${Math.max(1,Math.ceil((r.totalLength||r.length)/r.p.speed))}분 / ${Math.round(r.totalLength||r.length)}m`;$('#detail-dialog .demo-banner').textContent='실제 공개 도로 기반 · 미검증 연결 구간과 시설 상태를 확인하세요. 시뮬레이션과 GPS 안내를 선택할 수 있어요.';renderSteps();$('#next-step').textContent='시뮬레이션 시작 →';if(!$('#start-live')){const wrap=textEl('div','','detail-mode'),live=textEl('button','◎ GPS로 이동 확인','secondary');live.id='start-live';live.onclick=startTracking;wrap.append(live);$('#detail-dialog').append(wrap)}$('#detail-dialog').showModal()}
function renderSteps(){const c=$('#steps');c.replaceChildren();detailGroups.forEach((s,i)=>{const li=textEl('li',s.bench?s.name:s.name+' 따라 약 '+Math.round(s.length)+'m',currentStep===i?'current':'');li.append(textEl('small',s.bench?`보행로에서 벤치까지 약 ${Math.round(s.gap)}m · 연결과 시설 상태 미확인`:s.steps?'계단 구간 · 비교 경로 이용 주의':slopeGroupDescription(s)));c.append(li)})}
$('#next-step').onclick=()=>{currentStep++;if(currentStep>=detailGroups.length){currentStep=-1;$('#next-step').textContent='다시 체험하기 ↻';toast('시뮬레이션을 완료했어요. 실제 도착 여부를 확인한 것은 아닙니다.')}else $('#next-step').textContent=currentStep===detailGroups.length-1?'시뮬레이션 완료 ✓':'다음 구간 →';renderSteps();$('#steps .current')?.scrollIntoView({block:'nearest'})};
function stopTracking(notify=true){if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;$('#live-guidance').hidden=true;if(notify)toast('GPS 이동 확인을 종료했어요.')}
function startTracking(){if(!navigator.geolocation)return toast('브라우저가 위치 기능을 지원하지 않아요.');const r=routes[selected];if(!r)return;stopTracking(false);$('#detail-dialog').close();$('#live-guidance').hidden=false;$('#live-guidance').textContent='GPS 위치를 확인하고 있어요…';$('#live-map').scrollIntoView({behavior:'smooth',block:'center'});watchId=navigator.geolocation.watchPosition(pos=>{const ll=[pos.coords.latitude,pos.coords.longitude];if(gpsMarker)gpsMarker.remove();gpsMarker=L.circleMarker(ll,{radius:8,color:'white',weight:3,fillColor:'#438dc6',fillOpacity:1}).addTo(map);let best=Infinity,index=0;r.coords.forEach((c,i)=>{const d=E.distance(c,ll);if(d<best){best=d;index=i}});const remaining=r.edges.slice(index).reduce((s,e)=>s+e.d,0);const c=$('#live-guidance');c.replaceChildren(textEl('b',`GPS 정확도 ±${Math.round(pos.coords.accuracy)}m`),textEl('div',best>70?`경로에서 약 ${Math.round(best)}m 떨어져 있어요. 출발 위치를 확인해 주세요.`:`도로상 남은 거리 약 ${Math.round(remaining)}m · ${r.edges[index]?.name||'목적지 인근'}`),textEl('small','자동 재탐색·정확한 회전 안내는 지원하지 않아요.'));const stop=textEl('button','위치 확인 종료');stop.onclick=()=>stopTracking();c.append(stop)},err=>{stopTracking(false);toast(err.code===1?'위치 권한이 거부됐어요. 시뮬레이션을 이용할 수 있어요.':'GPS 위치를 받지 못했어요. 다시 시도해 주세요.')},{enableHighAccuracy:true,timeout:15000,maximumAge:5000})}
$('#save-route').onclick=()=>{const r=routes[selected];if(!r)return;const item={id:Date.now(),origin,originName,destination,condition:$('#condition').value,options:r.p,label:r.label};if(write('donghaeng.school.routes',[item,...read('donghaeng.school.routes')]))toast('이 브라우저에 경로 조건을 저장했어요.')};
$$('[data-view]').forEach(b=>b.onclick=()=>{if(isMobileUI())setMobileMode(b.dataset.view==='saved'?'saved':routes.length?'results':'input');$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('#planner').hidden=b.dataset.view!=='route';$('#saved-view').hidden=b.dataset.view!=='saved';$('.intro').hidden=b.dataset.view==='saved';if(b.dataset.view==='saved')renderSaved()});
function renderSaved(){const c=$('#saved-list'),items=read('donghaeng.school.routes');c.replaceChildren();if(!items.length)c.append(textEl('p','경로 상세에서 저장하면 여기에 나타나요.','empty-note'));items.forEach(item=>{const box=textEl('div','','saved-item');box.append(textEl('b',item.destination.name),textEl('p',item.condition));const open=textEl('button','이 조건으로 다시 찾기 →');open.onclick=()=>{setOrigin(item.origin,item.originName);setDestination(item.destination);setCondition(item.condition);$('[data-view="route"]').click();$('#search').requestSubmit()};const del=textEl('button','삭제');del.onclick=()=>{if(write('donghaeng.school.routes',items.filter(x=>x.id!==item.id)))renderSaved()};box.append(open,del);c.append(box)})}
function info(title,text){$('#info-title').textContent=title;$('#info-text').textContent=text;$('#info-dialog').showModal()}
$('#about').onclick=()=>info('월곡역에서, 나의 속도로','① 현재 위치 사용을 누르고 권한을 허용하세요. ② 월곡역 주변 목적지를 검색 결과에서 고르거나 지도에서 선택하세요. ③ 몸 상태를 입력하고 길 찾기를 누르면 자동 AI 해석과 경로 추천을 진행합니다. 조건을 따로 체크할 필요 없이 입력 문장을 자동으로 해석합니다. 길 찾기를 누르면 입력한 상태 문장만 서버를 거쳐 Google Gemini로 전송합니다. 위치·목적지·지도 자료는 보내지 않습니다. 연결 실패 시 기기 내 해석으로 전환합니다. 실제 OSM 도로 그래프를 탐색하고, 등록 계단 제외·경사 부담 가중치·등록 벤치 경유를 적용합니다. 서버로 실행하면 배경 지도 타일을 OpenStreetMap에서 받아 표시하며, 현재 보는 지도 영역의 타일 요청이 OSM 서버로 전송됩니다. 타일 연결 실패나 파일 단독 실행에서는 내장 공개 지도 자료를 표시합니다. Gemini에는 상태 문장만 보내며 서버는 이를 저장하지 않습니다. 경로/제보 저장은 이 브라우저에만 적용됩니다. 시설은 서울 전역 공개 자료이며, 경로는 월곡역 주변 내장 도로망을 사용합니다. 보도 턱·폭·출입구·경사는 OSM 표기와 기존 Tilezen 참고 추정을 구별하며, 서울시 표고·등고선과 Copernicus는 비교·위험 검토 범위로 구분하며 노면 실측 경사로 채택하지 않습니다. 지형 경사는 보도 실측이 아니며 짧은 급경사·턱·교량·지하를 보장하지 않습니다. 사진 확인과 실시간 이용 가능은 다릅니다. 이용 조건과 미확인 정보를 함께 확인해 주세요.');
$('#report-open').onclick=()=>{$('#report-place').value=destination?.name||originName;renderReports();$('#report-dialog').showModal()};$('#report-form').onsubmit=e=>{e.preventDefault();const p=$('#report-place').value.trim(),t=$('#report-text').value.trim();if(!p||!t)return toast('위치와 상세 내용을 입력해 주세요.');if(write('donghaeng.school.reports',[{place:p,text:t,type:$('#report-type').value,date:new Date().toLocaleDateString('ko-KR')},...read('donghaeng.school.reports')])){$('#report-form').reset();renderReports();toast('제보를 이 브라우저에 저장했어요. 경로에 자동 반영되지는 않습니다.')}};
function renderReports(){const c=$('#report-history'),items=read('donghaeng.school.reports');c.replaceChildren();if(items.length)c.append(textEl('b','내 제보 '+items.length+'건'));items.slice(0,5).forEach(x=>c.append(textEl('p',`${x.type} · ${x.place} / ${x.text}`)))}
$$('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.addEventListener('click',e=>{if(!e.target.closest('.destination-field'))$('#places').replaceChildren()});window.addEventListener('pagehide',()=>stopTracking(false));
async function hashRoadText(text){if(!globalThis.crypto?.subtle)return null;return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function loadTerrain(){try{const embedded=document.getElementById('bundled-terrain');let data;if(embedded)data=JSON.parse(embedded.textContent);else{const res=await fetch('terrain-data.json');if(!res.ok)throw Error('고도자료 로딩 실패');data=await res.json()}E.applyTerrain(graph,data);graph.meta.allowAssistancePreview=true;map.attributionControl.addAttribution('지형 © <a href="https://github.com/tilezen/joerd/blob/master/docs/attribution.md">Mapzen/Tilezen · USGS</a>')}catch{toast('추가 고도자료를 읽지 못해 OSM 경사 표기만 사용합니다.')}}
async function init(){try{await window.DONGHAENG_DATA_READY;map=L.map('live-map',{zoomControl:false,minZoom:3,maxZoom:19}).setView(F.STATION,17);L.control.zoom({position:'topright'}).addTo(map);L.control.scale({imperial:false,position:'bottomleft'}).addTo(map);await SeoulBaseMap.create(map);routeLayer.addTo(map);snapLayer.addTo(map);stageMarkers.addTo(map);stageFocus.addTo(map);facilityController=FacilityMap.create(map,{onSelectDestination:facilityDestination});const response=await fetch('map-data.json');if(!response.ok)throw Error('도로 데이터 로딩 실패');const roadText=await response.text();graph=E.createGraph(JSON.parse(roadText));graph.meta.graphSha256=await hashRoadText(roadText);await loadTerrain();routeLayer.bringToFront?.();map.on('click',ev=>{if(!pickMode)return;const ll=[ev.latlng.lat,ev.latlng.lng];if(!F.inCoverage(ll))return toast('월곡역 주변 내장 도로망 안에서 선택해 주세요.');if(pickMode==='origin')setOrigin(ll,'지도에서 지정한 출발지');else setDestination({ll,name:'지도에서 지정한 목적지'});pickMode=null;$('#map-instruction').hidden=true;if(isMobileUI())setSheetSize('default')});$('.facility-control').addEventListener('toggle',()=>{if(isMobileUI()&&$('.facility-control').open)setSheetSize('collapsed')});await facilityController.ready;facilityFeatures=facilityController.getFeatures();graph.benches=F.stopCandidates(facilityFeatures,E);graph.restPlaces=F.restCandidates(facilityFeatures,E);localDestinations=F.placeOptions(facilityFeatures,graph.places,E);resetTrip();$('#find-route').disabled=false;$('#data-note').textContent=`지도 자료 기반 경로 · 현재 위치·사진 추정 위치·운영 상태를 구분해 안내합니다. 경사·턱·출입구 미확인 구간은 현장에서 확인하세요.`;$('#search-status').textContent='월곡역 시연 준비 완료. 상태를 적고 길 찾기를 눌러 주세요.';renderDashboard();$('#boot-status').hidden=true;if(new URLSearchParams(location.search).get('demo')==='luna-wheelchair'){$('#luna-origin').click();chooseDestination('school');setCondition('휠체어를 이용해요. 경사와 계단을 피해서 가고 싶어요.');$('#search').requestSubmit()}}catch(e){$('#search-status').textContent='지도 준비 실패: '+e.message+' · 새로고침으로 다시 시도해 주세요.';$('#destination-status').textContent='데이터를 불러오지 못했어요.';$('#boot-status').textContent='준비 중 오류가 발생했어요. 새로고침하거나 이용 안내를 확인해 주세요.'}}

function facilityDestination(place){if(!F.inCoverage(place.ll)){toast('시설은 서울 전역에서 볼 수 있어요. 길 찾기는 월곡역 주변에서 지원합니다.');return false}setDestination(place);if(isMobileUI())setMobileMode('input');else $('#search').scrollIntoView({behavior:'smooth',block:'start'});toast('목적지를 선택했어요. 내 상태에 맞는 길을 찾아보세요.');return true}
function renderDashboard(){const stats=F.dashboard(facilityFeatures,E);$('#registered-records').textContent=stats.records.toLocaleString();$('#local-rest-count').textContent=stats.localRest;$('#data-source-caption').textContent=`등록 시설 ${stats.records.toLocaleString()}건 · 단지 경계·제보 구역 별도 · 현재 상태 미확인`;}
function renderPlanReason(r,p){const panel=$('#plan-reason');panel.hidden=false;panel.classList.toggle('risk-preview',!!r.assistancePreview);panel.replaceChildren();panel.append(textEl('b',r.assistancePreview?'급경사 회피 조건 미충족 · 독립 이동 추천 아님':r.comparison?'거리 우선 비교 경로 · 상태 제약 미적용':p.source==='Gemini'?'AI가 오늘의 상태를 경로에 반영했어요':'기기 내 해석으로 오늘의 경로를 추천했어요'));panel.append(textEl('small',p.source==='Gemini'?'상태 해석: Google Gemini':'상태 해석: 기기 내 해석 · AI 서버 응답 사용 안 함'));const rules=[];if(p.wheelchair)panel.append(textEl('p',r.assistancePreview?'급경사 회피 조건을 충족하지 못한 검토용 대안입니다. 휠체어 독립 이동을 추천하지 않습니다.':'휠체어 우회 후보 · 통행 안전 미확인. 5%는 참고 자료의 추천 회피 기준이며 안전 인증 기준이 아닙니다.'));if(p.avoidSteps)rules.push('등록 계단 제외');if(p.avoidSlope)rules.push('Tilezen 참고 추정·노면 부담 반영');if(p.maxSlope!=null)rules.push(r.assistancePreview?'요청 기준 '+p.maxSlope+'% 초과 위험 포함':'등록·참고 추정 '+p.maxSlope+'% 초과 추천 회피');if(p.rest)rules.push(p.restKind==='shelter'?'쉼터 우선 탐색':p.restKind==='bench'?'벤치·의자 우선 탐색':'벤치·쉼터 함께 탐색');if(p.short)rules.push('거리 우선');panel.append(textEl('p',rules.join(' · ')||'기본 보행 경로'));if(r.restStop)panel.append(textEl('p',(r.restStop.kind==='shelter'?'쉼터':'의자 휴식')+' · '+r.restStop.name));if(r.restStop?.kind==='shelter')panel.append(textEl('small',r.restStop.operatingNote));const evidence=r.slopeEvidence||E.slopeSummary(r.edges);panel.append(textEl('small',`OSM 수치표기 ${Math.round(evidence.osmMeters)}m · Tilezen 참고 지형 추정 ${Math.round(evidence.tilezenHintMeters)}m · 기존 단일값 없는 ${Math.round(evidence.unknownMeters)}m는 아래 보완 분류 확인`));if(evidence.conflictMeters>0||evidence.structuralMeters>0)panel.append(textEl('small',`자료 차이 ${Math.round(evidence.conflictMeters)}m · 구조물·계단 등 ${Math.round(evidence.structuralMeters)}m는 지형 추정 제외`));if(r.maxEstimatedSlope!=null)panel.append(textEl('small','Tilezen 도로 창 평균 추정 최대 약 '+r.maxEstimatedSlope.toFixed(1)+'% · 보도 실측 아님'));renderSlopeCoverage(panel,r);panel.append(textEl('small','서울 표고점·등고선과 Copernicus는 비교·위험 검토용 · 노면 경사·휠체어 통행 가능 미확인'));const button=textEl('button','자료 차이·출처 보기 ↗','terrain-source-link');button.type='button';button.onclick=()=>showSlopeEvidence(r);panel.append(button);if(isMobileUI()&&r.messages.length)panel.append(textEl('p',r.messages.join(' ')));renderMobileRouteStatus(r,p)}
function showSlopeEvidence(r){const evidence=r.slopeEvidence||E.slopeSummary(r.edges),lines=['OSM 수치는 도로에 등록된 표기이며 현장 검증을 뜻하지 않습니다.','Tilezen은 기존 도로 창의 평균 지형 추정입니다. 원시 DEM 실효 해상도·노면 고도는 미확인입니다.','서울시 표고점·등고선은 노면 실측 경사가 아니며 수직기준·관측 정확도가 확인되지 않아 비교만 합니다.','Copernicus GLO-30은 건물·수목을 포함하는 DSM(EGM2008)으로 비교만 하며 경로 값을 대체하지 않습니다.','자료 차이·교량·고가·터널·지하·층위 불명 구간은 지형 추정을 적용하지 않습니다. 자료 차이는 범위로, 짧은 도로는 60m 방향별 지형 참고 추정으로 위험을 검토합니다. 교량·지하 등은 별도 확인 대상으로 남깁니다. 경사 회피 조건이 충족되지 않으면 독립 이동 추천과 구분한 위험 대안으로 표시합니다. 이는 추천 규칙일 뿐 노면 경사 상한 충족이나 휠체어 통행 가능·불가능의 확정 판정이 아닙니다.'];if(graph.meta.terrain?.reviewState!=='current')lines.push('현재 비교 검증 자료가 연결되지 않았습니다. 기존 참고 추정만 표시합니다.');for(const example of evidence.examples){const signed=v=>Number.isFinite(v)?(v>0?'+':'')+v.toFixed(1)+'%':'추정 없음';lines.push(`\n${example.name} · OSM way/${example.wayId}\n같은 도로 창 약 ${example.supportM||100}m 비교: Tilezen ${signed(example.signedGrades.tilezen)} / Copernicus ${signed(example.signedGrades.copernicus)} / 서울 표고점 보간 ${signed(example.signedGrades.seoul_spots)}\n차이 ${Number(example.differencePp).toFixed(1)}%p · 어느 값이 정답인지는 미확인`) }lines.push('\n5%p 차이는 검증 대상을 고르는 보수적 정책값이며 정확도 기준이 아닙니다. 서로 다른 수직기준을 보정 없이 합치지 않습니다.','\n출처: 서울특별시 · 원천 국토지리정보원 수치지형도 · 공공누리 제1유형','Mapzen/Tilezen; SRTM/GMTED2010 terrain data courtesy of the U.S. Geological Survey','produced using Copernicus WorldDEM-30 © DLR e.V. 2010-2014 and © Airbus Defence and Space GmbH 2014-2018 provided under COPERNICUS by the European Union and ESA; all rights reserved');info('경사 자료의 출처와 한계',lines.join('\n\n'));for(const [label,url] of [['서울시 표고점·등고선','https://data.seoul.go.kr/dataList/OA-22241/F/1/datasetView.do'],['Copernicus DSM·이용조건','https://dataspace.copernicus.eu/explore-data/data-collections/copernicus-contributing-missions/collections-description/COP-DEM'],['Tilezen 자료·출처표시','https://github.com/tilezen/joerd/blob/master/docs/attribution.md']]){const a=textEl('a',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener noreferrer';$('#info-text').append(document.createElement('br'),a)}}

function updateRouteCallout(){
const r=routes[selected],panel=$('#route-callout');if(!r){panel.hidden=true;return}
// Keep disclosure state through redraws, but start a newly calculated trip compact.
const sameRoute=panel._route===r;panel.open=sameRoute&&panel.open;panel._route=r;
panel.hidden=false;panel.replaceChildren();
const heading=textEl('summary','','callout-heading'),title=r.assistancePreview?'경사 위험 대안 · 이동 지원 필요':r.comparison?'거리 중심 비교 경로':r.restStop?'쉬어 갈 곳을 연결했어요':'나의 이동 조건을 반영했어요';
heading.title=title+' · 눌러서 상세 안내 펼치기/접기';
heading.append(textEl('b',title),textEl('span',`${Math.max(1,Math.ceil((r.totalLength||r.length)/r.p.speed))}분 · ${Math.round(r.totalLength||r.length)}m`));
const content=textEl('div','','callout-content');panel.append(heading,content);
if(r.restStop){content.append(textEl('p',r.restStop.name));const why=textEl('button','휴식 장소 근거 보기 ↗');why.type='button';why.onclick=()=>facilityController.focusFeature(r.restStop.id);content.append(why)}else content.append(textEl('p',r.comparison?'입력한 접근성 조건을 적용하지 않은 비교용입니다.':'등록 정보에 근거한 경로예요. 미확인 구간도 함께 확인하세요.'));
if(routes.length>1){const basic=routes.find(x=>x.comparison),delta=basic?Math.round((r.totalLength||r.length)-(basic.totalLength||basic.length)):0;if(delta>0&&!r.comparison)content.append(textEl('small',`거리 우선 경로보다 ${delta}m 더 이동해요.`))}
content.append(textEl('small','소요 시간은 입력 상태에 따른 추정 · 실시간 교통·시설 가동 정보 아님'));
}
function chooseDestination(key){if(!graph)return;let place;if(key==='school')place=localDestinations.find(p=>p.name==='서울대학교사범대학부설중학교');else if(key==='library')place=localDestinations.find(p=>p.name==='월곡꿈그림도서관');else{const id=key==='triangle'?'review:wolgok-more:elevator-crosswalk-triangle':'review:wolgok-stop-kb-202606';const f=facilityFeatures.find(f=>f.id===id||f.properties.id===id);if(f)place={name:f.properties.name,ll:[f.geometry.coordinates[1],f.geometry.coordinates[0]],facilityId:f.id}}if(place)setDestination(place);else toast('장소 자료를 아직 준비하고 있어요.')}
$$('[data-destination]').forEach(b=>b.onclick=()=>chooseDestination(b.dataset.destination));
$('#mobile-map-jump').onclick=()=>{$('#live-map').scrollIntoView({behavior:'smooth',block:'start'});map?.invalidateSize()};
$('#demo-open').onclick=()=>$('#demo-dialog').showModal();
$$('[data-demo]').forEach(b=>b.onclick=()=>{if(!graph){toast('지도 준비가 끝나면 시연할 수 있어요.');return}resetTrip();setCondition(F.SCENARIOS[b.dataset.demo].text);$('#demo-dialog').close();$('#search').requestSubmit()});
$('#present-mode').onclick=()=>{if(!graph){toast('지도 준비가 끝나면 발표 모드를 사용할 수 있어요.');return}const on=document.body.classList.toggle('is-presenting');$('#present-mode').textContent=on?'입력 화면으로 ↙':'발표 모드 ↗';if(on){$('.facility-control').open=false;if(!routes.length){resetTrip();$('#search').requestSubmit()}}$('.sidebar').scrollTop=0;requestAnimationFrame(()=>{map?.invalidateSize();$('.sidebar').scrollTop=0;if(routes.length)drawRoutes(true)})};


// Mobile app shell shares the existing route engine, forms and storage.
let mobileMode='input',sheetSize='default',sheetDrag=null,sheetGestureUntil=0;
function isMobileUI(){return matchMedia('(max-width:700px)').matches}
function syncMobileViewport(){
 if(!isMobileUI()){document.documentElement.style.removeProperty('--app-height');document.body.classList.remove('keyboard-open');return}
 const viewport=window.visualViewport,height=viewport?.height||innerHeight;
 document.documentElement.style.setProperty('--app-height',Math.round(height)+'px');
 document.documentElement.style.setProperty('--app-top',Math.round(viewport?.offsetTop||0)+'px');
 const editing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName||'');
 document.body.classList.toggle('keyboard-open',editing&&innerHeight-height>100);
 const header=$('.header').getBoundingClientRect().height,nav=$('.mobile-tabs').getBoundingClientRect().height,available=height-header-nav;
 const desired=sheetSize==='collapsed'?64:sheetSize==='expanded'?available-54:Math.min(mobileMode==='order'?255:mobileMode==='results'?400:480,available*(mobileMode==='order'?.36:mobileMode==='results'?.52:.59));
 const sheet=Math.max(64,Math.min(available-44,Math.round(desired)));
 document.documentElement.style.setProperty('--sheet-height',sheet+'px');
 document.documentElement.style.setProperty('--mobile-nav-height',nav+'px');
 document.documentElement.style.setProperty('--map-bottom-space',(sheet+nav)+'px');
}
function setSheetSize(size){
 sheetSize=size;document.body.dataset.sheetSize=size;
 $('#sheet-toggle').setAttribute('aria-expanded',size!=='collapsed');
 $('#sheet-toggle-label').textContent=size==='collapsed'?'입력·결과 펼치기 ⌃':'지도 넓게 보기 ⌄';
 syncMobileViewport();
}
function setMobileMode(mode){
 mobileMode=mode;document.body.dataset.mobileMode=mode;
 $('#sheet-title').textContent=mode==='order'?'이동 순서':mode==='results'?'내 상태에 맞춘 경로':mode==='saved'?'저장한 경로':'어디로 갈까요?';
 $('#mobile-back').hidden=mode==='input';
 $$('[data-mobile-tab]').forEach(b=>{const active=b.dataset.mobileTab===(mode==='saved'?'saved':'route');if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 if(isMobileUI()){$('#planner').hidden=mode==='saved';$('#saved-view').hidden=mode!=='saved';$('.intro').hidden=mode==='saved';setSheetSize('default');$('.sheet-scroll').scrollTop=0}
}
function fitMobileAware(bounds){
 if(!map)return;
 if(isMobileUI()){syncMobileViewport();const size=map.getSize(),bottom=Math.min(size.y-100,parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--map-bottom-space'))+16||180);map.fitBounds(bounds,{paddingTopLeft:[24,55],paddingBottomRight:[24,bottom],maxZoom:18})}
 else map.fitBounds(bounds,{paddingTopLeft:[45,65],paddingBottomRight:[45,285],maxZoom:18});
}
function frameVisibleLocation(ll,zoom){if(!map)return;syncMobileViewport();const bottom=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--map-bottom-space'))||0;map.setView(map.unproject(map.project(ll,zoom).add([0,bottom/2]),zoom),zoom,{animate:false})}
function renderMobileRouteStatus(r,p){
 const applied=p||r.p||{};
 const status=$('#mobile-route-status');if(!status)return;
 status.classList.toggle('is-risk',!!r.assistancePreview);
 status.textContent=(applied.source==='Gemini'?'AI 해석 · ':'기기 내 해석 · ')+(r.assistancePreview?'이동 지원 필요 · 급경사 회피 조건 미충족. 독립 이동 추천이 아닙니다.':r.comparison?'거리 우선 비교용 · 입력한 이동 제약 미적용':applied.rest&&!r.restStop?'휴식 경유지를 찾지 못했어요 · 휴식 조건 미충족':'현장 통행·시설 상태 미확인 · 연결 구간을 확인해 주세요.');
}
function renderMobileStage(){
 const stage=journeyStages[activeStage],box=$('#mobile-stage');if(!box)return;
 box.replaceChildren();if(stage)box.append(textEl('b',stage.title),textEl('p',stage.sub));
}
function configureMobileLayout(){
 for(const selector of ['.origin-settings','.examples-disclosure','#route-evidence','.order-all','.route-limits'])$$(selector).forEach(e=>e.open=!isMobileUI());
 if(isMobileUI()){document.body.classList.remove('is-presenting');$('#present-mode').textContent='발표 모드 ↗';setMobileMode($('#saved-view').hidden?(routes.length?'results':'input'):'saved')}
 else{document.body.removeAttribute('data-mobile-mode');document.body.removeAttribute('data-sheet-size')}
 syncMobileViewport();map?.invalidateSize({pan:false});if(routes.length){renderRoutes();if(isMobileUI())fitMobileAware(L.latLngBounds([...routes[selected].coords,origin,destination.ll]))}
}
$('#sheet-toggle').onclick=()=>{if(Date.now()>=sheetGestureUntil)setSheetSize(sheetSize==='collapsed'?'default':'collapsed')};
const handle=$('#sheet-toggle');
handle.addEventListener('pointerdown',ev=>{if(ev.pointerType!=='touch'&&ev.button!==0)return;sheetDrag={id:ev.pointerId,y:ev.clientY,delta:0};handle.setPointerCapture(ev.pointerId)});
handle.addEventListener('pointermove',ev=>{if(sheetDrag?.id===ev.pointerId)sheetDrag.delta=ev.clientY-sheetDrag.y});
handle.addEventListener('pointerup',ev=>{if(sheetDrag?.id!==ev.pointerId)return;const d=sheetDrag.delta;sheetDrag=null;if(Math.abs(d)>32){setSheetSize(d>0?'collapsed':'expanded');sheetGestureUntil=Date.now()+250}});
handle.addEventListener('pointercancel',()=>sheetDrag=null);
$('#mobile-back').onclick=()=>{if(mobileMode==='order'){setMobileMode('results');if(routes[selected])fitMobileAware(L.latLngBounds(routes[selected].coords))}else setMobileMode('input')};
$('#mobile-edit').onclick=()=>setMobileMode('input');
$('#mobile-save').onclick=()=>$('#save-route').click();
$('#mobile-overview').onclick=()=>{setMobileMode('results');if(routes[selected])fitMobileAware(L.latLngBounds(routes[selected].coords))};
$('#mobile-detail').onclick=showDetails;
$$('[data-mobile-tab]').forEach(b=>b.onclick=()=>{const tab=b.dataset.mobileTab;if(tab==='report'){$('#report-open').click();return}if(tab==='saved'){renderSaved();setMobileMode('saved')}else setMobileMode(routes.length?'results':'input')});
$('#mobile-more').onclick=()=>$('#mobile-menu').showModal();
for(const [source,target] of [['mobile-about','about'],['mobile-demo','demo-open'],['mobile-reset','school-reset']])$('#'+source).onclick=()=>{$('#mobile-menu').close();$('#'+target).click()};
$('#mobile-map-jump').onclick=()=>{if(isMobileUI())setSheetSize('collapsed');else $('#live-map').scrollIntoView({behavior:'smooth',block:'start'});map?.invalidateSize()};
$('#search').addEventListener('focusin',ev=>{if(isMobileUI()&&ev.target.matches('input,textarea,select')){setSheetSize('expanded');requestAnimationFrame(()=>ev.target.scrollIntoView({block:'nearest'}))}});
function visualViewportChanged(){syncMobileViewport();if(isMobileUI()&&document.activeElement?.matches('input,textarea,select'))requestAnimationFrame(()=>document.activeElement?.scrollIntoView({block:'nearest'}))}
window.visualViewport?.addEventListener('resize',visualViewportChanged);window.visualViewport?.addEventListener('scroll',syncMobileViewport);
window.addEventListener('resize',syncMobileViewport);
matchMedia('(max-width:700px)').addEventListener('change',configureMobileLayout);
document.addEventListener('focusout',()=>requestAnimationFrame(syncMobileViewport));
configureMobileLayout();

init();

function slopeDescription(e){const info=e.slopeScreening,actual=E.slopeOf(e);if(e.incline!=null)return 'OSM 등록 '+e.incline.toFixed(1)+'% · 현장 미검증';if(info?.kind==='structure_unresolved')return '구조물·계단 등 · 노면 고도 별도 확인 필요';if(info?.kind==='no_dem')return '고도 자료 범위 밖 또는 결측 · 경사 미확인';if(info&&Number.isFinite(info.maxPercent)){const value=Math.abs(info.maxPercent-info.minPercent)<.05?info.maxPercent.toFixed(1):info.minPercent.toFixed(1)+'~'+info.maxPercent.toFixed(1);return (info.kind==='source_range'?'자료 간 참고 범위 ':info.kind==='neighborhood_proxy'?'주변 지형 60m 방향 추정 ':'Tilezen 도로 창 참고 추정 ')+value+'% · 노면 실측 아님'}return actual!=null?'참고 추정 '+actual.toFixed(1)+'% · 노면 미검증':'경사 자료 없음 · 현장 확인 필요'}
function renderSlopeCoverage(panel,r){const stats=r.screeningMeters;if(!stats)return;const upper=r.edges.map(E.screeningGrade).filter(Number.isFinite);if(upper.length)panel.append(textEl('p',`참고 자료 범위 상단 최대 ${Math.max(...upper).toFixed(1)}% · 실측 최대 경사 아님`));panel.append(textEl('p',`전체 ${r.edges.length}구간 검토 · 참고값 ${Math.round(stats.estimated)}m · 자료 차이 범위 ${Math.round(stats.range)}m · 구조물 ${Math.round(stats.structure)}m · 고도 결측 ${Math.round(stats.missing)}m`));if(r.assistancePreview){panel.append(textEl('p',`노면 미확인 통과량을 먼저 줄인 뒤 최대 참고 경사를 최소화해 탐색 · 선택 상단 ${r.assistanceCeiling?.toFixed(1)??'미확인'}% · 안전 기준 충족 아님`));panel.append(textEl('strong','위험 구간이 남아 있어 이동 지원과 현장 동선 확인이 필요합니다.'));}const detail=textEl('details','','slope-coverage'),summary=textEl('summary','구간별 경사와 주의점 모두 보기');detail.append(summary);const list=textEl('ol','','slope-segments');r.edges.forEach((e,i)=>{const item=textEl('li','');item.append(textEl('b',`${i+1}. ${e.name} · ${Math.round(e.d)}m`),textEl('span',slopeDescription(e)));const button=textEl('button','지도에서 보기');button.type='button';button.onclick=()=>{if(isMobileUI())setSheetSize('collapsed');fitMobileAware(L.latLngBounds([r.coords[i],r.coords[i+1]]));if(innerWidth<=700)$('#live-map').scrollIntoView({behavior:'smooth',block:'center'})};item.append(button);list.append(item)});detail.append(list);detail.append(textEl('small',`출발 연결 ${Math.round(r.gaps[0])}m·도착 연결 ${Math.round(r.gaps[1])}m는 내장 도로망 밖 연결이며 노면 경사·진입 미검증입니다.`));panel.append(detail)}
$('#luna-origin').onclick=()=>{if(!graph)return;setOrigin([37.5995513,127.0412035],'루나밸리 서측 경계 · 시연 기준점');$('#location-status').textContent='OSM 단지 경계의 시연 지점이며 확인된 출입구가 아닙니다. 실제 출발 위치는 GPS 또는 지도에서 조정해 주세요.';map.setView(origin,18)};

function slopeGroupDescription(s){const edges=s.slopeEvidenceEdges||[],values=edges.map(E.screeningGrade).filter(Number.isFinite),kinds=new Set(edges.map(e=>e.slopeScreening?.kind));const notes=[];if(values.length)notes.push('참고 자료 범위 상단 최대 '+Math.max(...values).toFixed(1)+'% · 실측 아님');if(kinds.has('source_range'))notes.push('자료 차이 포함');if(kinds.has('structure_unresolved'))notes.push('구조물 노면 미확인 포함');if(kinds.has('no_dem'))notes.push('고도 결측 포함');return notes.join(' · ')||'전체 구간 목록의 근거를 확인해 주세요.'}
